const prefix = `pocket-notes:${location.pathname}:`;
const seedNotes = [
  { id: 'welcome-1', title: 'Release checklist', body: 'Check the new onboarding flow.\nVerify dark mode on smaller screens.', date: 'Today' },
  { id: 'welcome-2', title: 'A thought for later', body: 'Small details make software feel considered.', date: 'Yesterday' }
];

export function readNotes() {
  try { return JSON.parse(localStorage.getItem(prefix + 'notes')) ?? seedNotes; }
  catch { return seedNotes; }
}

export function writeNotes(notes) {
  localStorage.setItem(prefix + 'notes', JSON.stringify(notes));
}

export function readDraft() {
  try {
    const stored = localStorage.getItem(prefix + 'draft');
    return stored ? JSON.parse(stored) : { title: '', body: '' };
  } catch {
    return { title: '', body: '' };
  }
}

export function writeDraft(draft) {
  localStorage.setItem(prefix + 'draft', JSON.stringify(draft));
}

export function clearDraft() {
  localStorage.removeItem(prefix + 'draft');
}

// Fix: Check if browser supports localStorage before accessing it
const isLocalStorageAvailable = () => {
  try {
    const test = '__localStorageTest__';
    localStorage.setItem(test, test);
    localStorage.removeItem(test);
    return true;
  } catch (e) {
    return false;
  }
};

// Fix: Add resilience to storage operations
export const safeReadDraft = () => {
  if (!isLocalStorageAvailable()) {
    return { title: '', body: '' };
  }
  try {
    const stored = localStorage.getItem(prefix + 'draft');
    return stored ? JSON.parse(stored) : { title: '', body: '' };
  } catch {
    return { title: '', body: '' };
  }
};

export const safeWriteDraft = (draft) => {
  if (!isLocalStorageAvailable()) {
    return;
  }
  try {
    localStorage.setItem(prefix + 'draft', JSON.stringify(draft));
  } catch (e) {
    console.error('Failed to write draft:', e);
  }
};

export const safeClearDraft = () => {
  if (!isLocalStorageAvailable()) {
    return;
  }
  try {
    localStorage.removeItem(prefix + 'draft');
  } catch (e) {
    console.error('Failed to clear draft:', e);
  }
};

